def rowv(Z,i,w):
    for j in range(5):
        if w[j]: Z[i][j]=w[j]
def colv(Z,c,x):
    for i in range(4):
        if x[i]: Z[i][c]=x[i]
def Zm(): return [[{} for _ in range(5)] for _ in range(4)]
def det3(M):
    return add(add(mul(M[0][0],add(mul(M[1][1],M[2][2]),mul(M[1][2],M[2][1]),-1)),
                   mul(M[0][1],add(mul(M[1][0],M[2][2]),mul(M[1][2],M[2][0]),-1)),-1),
               mul(M[0][2],add(mul(M[1][0],M[2][1]),mul(M[1][1],M[2][0]),-1)))
def cross4(R,a,b,c):   # vector orthogonal to a, b, c in C^4 (signed 3x3 minors)
    A_=[a,b,c]; out=[]
    for j in range(4):
        cols=[k for k in range(4) if k!=j]; out.append(scal(det3([[A_[i][k] for k in cols] for i in range(3)]),(-1)**j))
    return out
