def U0span(R,u4,cols):
    # spanning set of {a on the 4 columns 'cols' : sum a = 0, <a,u4> = 0}, embedded in C^5 (other column 0)
    c=R.const; one=[c(1)]*4; out=[]
    for k in range(4):
        ek=[c(1) if j==k else {} for j in range(4)]; g=cross4(R,one,u4,ek); w=[{}]*5
        w=[{} for _ in range(5)]
        for t,col in enumerate(cols): w[col]=g[t]
        out.append(w)
    return out
