def c3p(u):   # orthogonal complement inside H_34 (columns 0,1,2) of u = (u0,u1,u2,0,0)
    return [add(u[1],u[2],-1),add(u[2],u[0],-1),add(u[0],u[1],-1),{},{}]
def dotp(a,b):
    t={}
    for x,y in zip(a,b):
        if x and y: t=add(t,mul(x,y))
    return t
