from fractions import Fraction as Fr
def evalp(q,pt):
    s=Fr(0)
    for k,v in q.items():
        t=Fr(v)
        for e,x in zip(k,pt): t*=x**e
        s+=t
    return s
def rank_fr(M):
    M=[row[:] for row in M]; rk=0; ncol=len(M[0]) if M else 0
    for c in range(ncol):
        piv=next((i for i in range(rk,len(M)) if M[i][c]!=0),None)
        if piv is None: continue
        M[rk],M[piv]=M[piv],M[rk]
        for i in range(len(M)):
            if i!=rk and M[i][c]!=0:
                f=M[i][c]/M[rk][c]; M[i]=[a-f*b for a,b in zip(M[i],M[rk])]
        rk+=1
    return rk
def greedy(pt):
    Ae=[[evalp(q,pt) for q in row] for row in Arows]
    order=list(range(len(Ae))); random.shuffle(order); rows=[]
    for i in order:
        if rank_fr([Ae[j] for j in rows+[i]])>len(rows): rows.append(i)
        if len(rows)==r: break
    sub=[Ae[i] for i in rows]; corder=list(range(25)); random.shuffle(corder); cols=[]
    for c in corder:
        if rank_fr([[row[j] for j in cols+[c]] for row in sub])>len(cols): cols.append(c)
        if len(cols)==r: break
    return sorted(rows),sorted(cols)
import numpy as _np, cmath as _cm
def greedy_num(pt):
    Ae=_np.array([[complex(sum(complex(v)*_np.prod([complex(x)**e for x,e in zip(pt,kk)]) for kk,v in q.items())) if q else 0 for q in row] for row in Arows])
    order=list(range(len(Ae))); random.shuffle(order); rows=[]
    for i in order:
        if _np.linalg.matrix_rank(Ae[rows+[i]],tol=1e-8*max(1,_np.abs(Ae).max()))>len(rows): rows.append(i)
        if len(rows)==r: break
    sub=Ae[rows]; corder=list(range(25)); random.shuffle(corder); cols=[]
    for c_ in corder:
        if _np.linalg.matrix_rank(sub[:,cols+[c_]],tol=1e-8*max(1,_np.abs(sub).max()))>len(cols): cols.append(c_)
        if len(cols)==r: break
    return sorted(rows),sorted(cols)
